/// <summary>
/// Example UPSPricingAttribute of table <c>EcoResProduct</c> field DisplayProductNumber.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeEcoResProductDisplayProductNumber extends UPSPricingAttributeEcoResProduct implements UPSIPricingAttribute
{
}

Method.Source:
public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    EcoResProduct ecoResProduct;
    while select DisplayProductNumber from ecoResProduct
    {
        ret.add(ecoResProduct.DisplayProductNumber);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(EcoResProduct, DisplayProductNumber));
    qbr.value(any2Str(_value));
}
